import{_ as e,o as n,c as p,a3 as t}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"《万历十五年》纪事","description":"","frontmatter":{},"headers":[],"relativePath":"books/wanli-shiwunian/22-《万历十五年》纪事.md","filePath":"books/wanli-shiwunian/22-《万历十五年》纪事.md","lastUpdated":1794316978000}'),o={name:"books/wanli-shiwunian/22-《万历十五年》纪事.md"};function i(_,a,r,s,c,l){return n(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="《万历十五年》纪事" tabindex="-1">《万历十五年》纪事 <a class="header-anchor" href="#《万历十五年》纪事" aria-label="Permalink to &quot;《万历十五年》纪事&quot;">​</a></h1><p>1976年　黄仁宇完成《万历十五年》英文书稿。</p><p>1981年　美国耶鲁大学出版社出版《万历十五年》英文本：1587，A Year of No Significance：The Ming Dynasty in Decline。</p><p>1982年　中华书局出版《万历十五年》中文本。其后重印本收录两段《神宗实录》和黄仁宇《〈万历十五年〉和我的“大”历史观》一文。1587，A Year of No Significance获美国国家图书奖（National Book Award）该年及次年两次提名（历史类作品）。</p><p>1985年　台湾食货出版社出版《万历十五年》中文繁体版。</p><p>1997年　列入三联书店“黄仁宇作品系列”出版。</p><p>1999年　入选《新周刊》、《书城》“改革开放20年来对中国影响最大的20本书”。<a href="./22-《万历十五年》纪事">[1]</a> 2006年　中华书局出版《万历十五年》（增订纪念本），增收黄仁宇《1619年的辽东战役》、富路特《英文版序言》、欧蒲台《万历：漫长的怠政时代》及黄粹存《皇帝只是个牌位》四文，精选数十幅黑白图片和十一张彩色图片插入书中，并特别收录黄仁宇晚年照片一帧及其夫人格尔女士所绘肖像一幅。</p><p>2007年　中华书局出版《万历十五年》（增订本），保留增订纪念本全部文字校核、增补成果，并增收黄仁宇书信手迹一份。</p><p>2008年　入选《中国图书商报》“改革开放30年最具影响力的300本书”和第九届深圳读书月“30年30本书”。</p><p>2009年　获搜狐网“读本好书”经典好书奖。</p><p>2014年　中华书局出版《万历十五年》（经典版），以增订纪念本为基础，进一步完善全书文字，增收多幅彩色历史图片，并特别制作《经典的历程——〈万历十五年〉中文之旅》，以飨读者。</p><p>————————————————————</p><p><a href="./22-《万历十五年》纪事">[1]</a> 编者按：《万历十五年》自1982年出版后，三十多年来畅销不衰，经常见于各色人等与报刊的推荐书单以及书店销售排行榜，此处从略，仅列比较重要的媒体评选榜单。</p>',13)])])}const h=e(o,[["render",i]]);export{f as __pageData,h as default};
